// Assemble an installed tree from explicit source families; never copy the development state.
import { existsSync, lstatSync, readFileSync, readdirSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { frameworkVersion, DOCUMENT_DEFAULTS } from './project-config.mjs';
import { describeProjectModules, enabledProjectModules } from './project-modules.mjs';
import { selectToolset } from './toolset-selection.mjs';
import { hashBytes } from './installation-transaction.mjs';
import { projectRelativePath } from './project-config.mjs';

export const FRAMEWORK_SOURCE = dirname(dirname(fileURLToPath(import.meta.url)));
const optional = new Set(['core/audit-ledger.mjs','core/acceptance.mjs','core/translations.mjs',
  'core/session-log.mjs','lib/token-report.mjs','lib/telegram-notify.sh','lib/telegram-notify.ps1']);
function files(root,directory) {
  const folder=join(root,directory);
  if(!existsSync(folder)) return [];
  return readdirSync(folder,{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name,'en')).flatMap(entry=>{
    const path=join(folder,entry.name);
    if(lstatSync(path).isSymbolicLink()) throw new Error('Framework source must not contain symlinks');
    return entry.isDirectory()?files(root,relative(root,path)):[relative(root,path).replaceAll('\\','/')];
  });
}
export function renderAgentGuide(config,{rules=[]}={}) {
  const roles=Object.entries(config.documents).map(([role,document])=>`- ${role}: ${document.path}${document.name?` (name ${document.name})`:''}`).join('\n');
  const checks=(config.inventory.checks||[]).map(check=>`- ${check.path}: ${JSON.stringify(check.argv)} in ${check.cwd}`).join('\n');
  return `# 0-CODE cycle instructions\n\nRead .0-code/config.json first. Its document roles, language, modules, engine settings and project inventory are authoritative; this guide is regenerated by install/upgrade.\n\n## Document roles\n\n${roles}\n\nWrite cycle documents in ${config.language}; these instructions stay in English. Built-in templates are in .0-code/templates; the configured project template role has priority.\n\n## Each turn\n\n1. Read the state and roadmap roles and the active cycle prompt.\n2. Execute concrete work for the current stage and record evidence. A prompt can contain many tasks of different kinds.\n3. Update state atomically: pipe a JSON patch to node .0-code/lib/update-state.mjs <state-role-path>. Moving current_version, current_stage or current_prompt_file requires next_step_prompt in the same patch. Never edit next_step_prompt_meta manually.\n4. Commit completed pieces according to the cycle prompt. The driver decides whether to continue or stop.\n\nStages: 0 goals; 1 planning; 2 execution; 3 audits; 4 testing. Blockers must reflect missing resources or genuine failed approaches. Limits are opt-in. One folder has one active cycle; parallel cycles need separate folders and branches. Meaningful architectural choices require at least three documented alternatives, grounds and a falsifiable outcome. Released acceptance criteria require evidence.\n\n## Long-running work\n\nLaunch it in the background and register pid, log, started_at, expect_by and exactly one completion signal under running_jobs: done_marker is literal log text, done_file is a readable regular result file path. Truncate the log or remove the old result file before launch; files older than started_at are ignored. Finished means collect the result, not success: ok=false remains a failed result. Do other work or end the turn; never poll in a sleeping shell loop. Collect finished results and remove their entries; inspect died or overdue jobs.\n\n## Project tools\n\nRead config.inventory.tools before choosing tools. Project definitions take precedence over identically named 0-CODE tools. Native locations and compatible content are distinct; adapters must report unsupported fields. Enabled modules: ${enabledProjectModules(config).join(', ')||'core only'}.\n\n## Checks found in this project\n\n${checks||'No build/test commands were identified; inspect the project before choosing commands.'}\n\n${rules.length?`Read applicable general rules from ${rules.map(path=>'.0-code/'+path).join(' and ')}; owner instructions and project conventions take precedence.\n`:''}`;
}
export function assembleInstallationBundle(config,{source=FRAMEWORK_SOURCE}={}) {
  const enabled=enabledProjectModules(config),output=new Map(),version=frameworkVersion(source);
  const catalog=enabled.includes('toolset')?JSON.parse(readFileSync(join(source,'toolset/catalog.json'),'utf8')):null;
  const selection=catalog?selectToolset(catalog,config):{selected:[],overridden:[]};
  const put=(target,bytes)=>{
    if(output.has(target)) throw new Error('Duplicate file in framework bundle');
    output.set(target,Buffer.from(bytes));
  };
  const copy=(from,to=from)=>{
    const file=join(source,from),stat=lstatSync(file);
    if(!stat.isFile()||stat.isSymbolicLink()) throw new Error('Framework source is not an ordinary file');
    put(to,readFileSync(file));
  };
  for(const family of ['core','lib']) for(const path of files(source,family)) {
    if(path.endsWith('.mjs')&&!optional.has(path)) copy(path);
  }
  for(const path of ['VERSION','schemas/config.schema.json','hooks/ralph-loop-stop','hooks/ralph-loop-stop.mjs','hooks/safety-guard','hooks/safety-guard.mjs','hooks/run-hook.cmd','tools/0code.mjs','tools/mcp-reference-run.mjs','templates/cycle.md']) copy(path);
  if(existsSync(join(source,'config/legacy-installations.json')))copy('config/legacy-installations.json');
  copy(existsSync(join(source,'schemas/STATE.schema.json'))?'schemas/STATE.schema.json':join(dirname(DOCUMENT_DEFAULTS.state.path),'schemas/STATE.schema.json'),'schemas/STATE.schema.json');
  for(const name of ['research','update','roadmap','guideline','decision']) {
    const current=`templates/${name}.md`,legacy=`${DOCUMENT_DEFAULTS.templates.path}/${name}.md`;
    if(existsSync(join(source,current))) copy(current);
    else if(existsSync(join(source,legacy))) copy(legacy,`templates/${name}.md`);
  }
  put('.gitignore','run/\n');
  put('.gitattributes','* -text -filter -working-tree-encoding -ident\n');
  put('AGENT.md',renderAgentGuide(config,{rules:config.toolset.scope==='project'?selection.selected.filter(entry=>entry.kind==='rules').map(entry=>entry.source):[]}));
  put('skills/orchestrator-wrapper/SKILL.md',`---\nname: orchestrator-wrapper\ndescription: Read the configured cycle state and roadmap, execute the current stage, and update state atomically.\n---\nRead .0-code/AGENT.md and .0-code/config.json. Work according to their document roles and active cycle prompt. The driver owns loop continuation.\n`);
  if(enabled.includes('audits')) {
    for(const path of ['core/audit-ledger.mjs','core/acceptance.mjs','commands/productionaudit.md','commands/productionauditloop.md']) copy(path);
    for(const path of files(source,'templates').filter(path=>/\/audit_.*\.md$|\/testing\.md$/.test(path))) copy(path);
    for(const path of files(source,DOCUMENT_DEFAULTS.templates.path).filter(path=>/\/audit_.*\.md$|\/testing\.md$/.test(path))) {
      const target='templates/'+path.split('/').at(-1);if(!output.has(target)) copy(path,target);
    }
  }
  if(enabled.includes('session_logs')) for(const path of ['hooks/save-session-log','hooks/save-session-log.mjs','core/session-log.mjs']) copy(path);
  if(enabled.includes('token_usage')) for(const path of ['hooks/usage-statusline','hooks/usage-statusline.mjs','lib/token-report.mjs']) copy(path);
  if(enabled.includes('telegram')) for(const path of ['lib/telegram-notify.sh','lib/telegram-notify.ps1']) copy(path);
  if(enabled.includes('pm2')) put('ecosystem.json',JSON.stringify({apps:[{name:'0-code',script:'core/supervisor.mjs',cwd:'.0-code',args:['--backend',config.engines[0]],autorestart:false}]},null,2)+'\n');
  if(enabled.includes('mcp_catalog')) {
    const manifest=existsSync(join(source,'config/mcp-manifest.json'))?'config/mcp-manifest.json':'config/mcp-manifest.example.json';
    copy(manifest,'config/mcp-manifest.json');copy('config/mcp-manifest.schema.json');
  }
  if(enabled.includes('toolset')) {
    copy('toolset/catalog.json');copy('toolset/CATALOG.md');
    for(const entry of selection.selected.filter(entry=>config.toolset.scope==='project'&&entry.kind!=='mcp')) for(const file of entry.files) {
      const path=projectRelativePath(file.path);
      if(!path.startsWith(`toolset/${entry.kind}/`)) throw new Error('Toolset asset is outside its source family');
      if(hashBytes(readFileSync(join(source,path)))!==file.sha256) throw new Error(`Toolset source differs from catalog: ${entry.id}`);
      if(!output.has(file.path)) copy(file.path);
    }
  }
  const descriptions=describeProjectModules();
  for(const id of enabled) put(`modules/${id}.json`,JSON.stringify({id,...descriptions[id]},null,2)+'\n');
  return {version,files:output,modules:enabled,selection};
}
